html,body{overflow:hidden!important;background:#fff!important}
#v63-launcher{display:none!important}
#v63-metadata-shell{width:100%!important;max-width:100%!important;right:0!important;top:0!important;height:100dvh!important;min-height:100dvh!important}
#v63-metadata-shell>div{width:100%!important;max-width:100%!important;height:100dvh!important}
#v62-main-tabs{display:flex!important;min-width:0;overflow-x:auto;scrollbar-width:none}
#v62-main-tabs::-webkit-scrollbar{display:none}
#v62-main-tabs li{padding-left:10px!important;padding-right:10px!important}
#v62-main-tabs li span{font-size:12px!important;white-space:nowrap}
#bridge-v83-version-tab[aria-selected=true]{box-shadow:inset 0 -2px var(--accentContent,#3f50ce)}
#bridge-v83-version-pane{padding:0 0 35px;font-family:Manrope,sans-serif;color:var(--primaryDarkContent,#252428)}
#bridge-v83-version-pane[hidden]{display:none!important}
.v83-v-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:3px 0 4px}
.v83-v-head h3{font-size:15px;font-weight:700;margin:0}
.v83-v-subtitle,.v83-v-description,.v83-v-footnote{font-size:11px;color:var(--secondaryContent,#777481);line-height:1.5}
.v83-v-description{margin:4px 0 17px}
.v83-vgroup{border-top:1px solid var(--secondaryBorder,#ededf1);padding:15px 0 10px}
.v83-vgroup-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px;gap:8px}
.v83-vgroup-heading strong{font-size:12px;font-weight:700}
.v83-vgroup-heading span{font-size:11px;color:var(--secondaryContent,#777481)}
.v83-vrow{position:relative;display:flex;align-items:center;gap:9px;padding:6px 2px;min-height:47px;border-radius:7px}
.v83-vrow:hover{background:var(--neutralSoftBg,#f5f5f7)}
.v83-vrow-content{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
.v83-vrow-content strong{font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v83-vrow-content small{font-size:10.5px;font-weight:400;color:var(--secondaryContent,#777481);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v83-iconbutton{width:30px;height:30px;flex:none;border:0;background:transparent;border-radius:6px;cursor:pointer;color:var(--primaryDarkContent,#252428);font-size:14px}
.v83-iconbutton:hover{background:var(--neutralSoftBg,#eeeef1)}
.v83-main-chip{font-size:10px;color:#777481;background:#f0f0f3;border-radius:5px;padding:3px 7px}
.v83-row-menu{position:absolute;right:0;top:35px;background:white;border:1px solid var(--secondaryBorder,#e7e7ed);border-radius:8px;padding:5px;z-index:300;box-shadow:0 8px 24px #25242822}
.v83-row-menu button{display:block;width:125px;text-align:left;border:0;background:white;font-size:12px;padding:9px;border-radius:5px}
.v83-row-menu button:hover{background:#f3f3f6}
.v83-v-cta{display:flex;gap:8px;flex-wrap:wrap;padding-top:16px;border-top:1px solid var(--secondaryBorder,#e8e8ec)}
.v83-borderbutton{min-height:35px;border:1px solid var(--secondaryBorder,#e3e3e8);background:transparent;border-radius:8px;color:var(--primaryDarkContent,#26252b);font-size:11.5px;font-weight:650;padding:8px 11px;cursor:pointer}
.v83-borderbutton:hover{background:var(--neutralSoftBg,#f5f5f7)}
.v83-v-footnote{margin-top:15px}
@media(max-width:440px){#v62-main-tabs li{padding-left:8px!important;padding-right:8px!important}#v62-main-tabs li span{font-size:11px!important}}

.v83-panel-host{width:100%;height:100dvh;overflow:hidden;background:#fff}
.v83-panel-host>#v63-metadata-shell{position:fixed!important;top:0!important;right:0!important;left:0!important;width:100%!important;height:100dvh!important;z-index:99!important;visibility:visible!important}
.v83-panel-host #v63-metadata-shell .v83-panel-close{position:absolute!important;right:13px!important;top:14px!important;z-index:9999!important;background:#fff!important;border:1px solid #e7e7eb!important;color:#777!important;border-radius:7px!important;width:27px!important;height:27px!important;font-size:22px!important;cursor:pointer!important;display:grid!important;place-items:center!important}

/* Bridge V83 isolated V80 metadata-panel bridge.
   Original public/metadata-v80.html is an exact byte-for-byte copy of GitHub V80.
   No V81 or V82 code is loaded. This adapter only attaches a Versions tab and
   mediates events with the parent React application. */
(()=>{
"use strict";
if(window.__bridgeCleanPanel)return;window.__bridgeCleanPanel=true;
const doc=document, parent=window.parent, $=id=>doc.getElementById(id);
const send=(type,data={})=>parent.postMessage({bridgeV83:true,type,...data},location.origin);
const style=doc.createElement("link");style.rel="stylesheet";style.href="/panel-bridge.css";doc.head.append(style);
function init(){
 const tabs=$("v62-main-tabs"),file=$("bridge-file-panel"),launcher=$("v63-open-meta");
 if(!tabs||!file){send("PANEL_ERROR",{message:"Canonical V80 tabs/file not found"});return;}
 const shell=$("v63-metadata-shell")||doc.querySelector(".v83-panel-host > div");
 if(shell&&!shell.id)shell.id="v63-metadata-shell";
 if(launcher)launcher.click();
 if(shell){shell.style.display="block";shell.style.visibility="visible";shell.style.width="100%";shell.style.right="0";shell.style.top="0";}
 let close=shell?.querySelector(".v63-meta-close");
 if(!close&&shell){close=doc.createElement("button");close.type="button";close.className="v83-panel-close";close.textContent="×";close.setAttribute("aria-label","Close metadata panel");shell.append(close);}
 if(close)close.addEventListener("click",e=>{e.preventDefault();e.stopImmediatePropagation();send("PANEL_CLOSE");},true);
 const versionsTab=doc.createElement("li");versionsTab.id="bridge-v83-version-tab";
 versionsTab.className="group relative flex h-12 cursor-pointer items-center px-xs hover:bg-neutralSoftBg";
 versionsTab.role="tab";versionsTab.tabIndex=-1;versionsTab.setAttribute("aria-selected","false");
 versionsTab.innerHTML='<span class="text-secondaryContent">Versions</span>';
 const fileTab=tabs.querySelector('[data-v62-section="file"]');fileTab.before(versionsTab);
 const pane=doc.createElement("section");pane.id="bridge-v83-version-pane";pane.className="meta-custom";pane.hidden=true;
 pane.setAttribute("role","tabpanel");pane.setAttribute("aria-labelledby","bridge-v83-version-tab");file.after(pane);
 let master={name:"Hardcore",artist:"Johnny Jane"},children=[],selectedVersion=null,activeSection="metadata";
 const node=(tag,cls,txt)=>{const el=doc.createElement(tag);if(cls)el.className=cls;if(txt!==undefined)el.textContent=txt;return el;};
 const button=(txt,cls,cb)=>{const b=node("button",cls,txt);b.type="button";b.addEventListener("click",cb);return b;};
 const sectionList=(title,records)=>{
  const box=node("section","v83-vgroup");const h=node("div","v83-vgroup-heading");
  h.append(node("strong","",title),node("span","",String(records.length)));box.append(h);
  for(const record of records){
    const row=node("div","v83-vrow"),play=button("","v83-iconbutton",()=>send("PLAY_VERSION",{trackId:record.id}));
    play.textContent="▶";play.setAttribute("aria-label","Play "+record.name);row.append(play);
    const description=node("div","v83-vrow-content");
    const name=node("strong","",record.name);
    const meta=node("small","",(record.type||"Mix")+(record.duration?" · "+record.duration:"")+(record.fileName?" · "+record.fileName:""));
    description.append(name,meta);row.append(description);
    if(title==="Original")row.append(node("span","v83-main-chip","Main"));
    else{
      const opt=button("···","v83-iconbutton",()=>{const menu=row.querySelector(".v83-row-menu");if(menu){menu.remove();return;}pane.querySelectorAll(".v83-row-menu").forEach(e=>e.remove());const m=node("div","v83-row-menu");
        m.append(button("Rename", "",()=>{const next=window.prompt("Version name",record.name);if(next?.trim())send("RENAME_VERSION",{trackId:record.id,name:next.trim()});m.remove();}));
        m.append(button("Unlink", "",()=>{send("UNLINK_VERSION",{trackId:record.id});m.remove();}));
        row.append(m);
      });opt.setAttribute("aria-label","More actions for "+record.name);row.append(opt);
    }
    box.append(row);
  }
  pane.append(box);
 };
 function render(){
  pane.replaceChildren();
